let g;
let vn = 0;
let palette;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  cam = createCamera();
  let d = max(width, height) / 2;
  g = createGraphics(d, d);
  palette = shuffle(random(colorScheme).colors);
  cam.lookAt(0, 0, 1);
}

function draw() {
  background(0);
  randomSeed(0);
  cam.perspective(
    PI /
      map(constrain(abs(tan((frameCount / 1000) % PI)), 0, 100), -1, 1, 0, 2),
    width / height,
    0.01,
    15000
  );
  let v = easeInOutCirc((frameCount / 300) % 1);
  let d = g.width;
  if ((frameCount / 300) % 1 == 0) {
    vn++;
  }

  g.blendMode(BLEND);
  g.background(0);
  // g.blendMode(ADD);

  separateGrid(0, 0, d, d / 10, (frameCount / 300) % 1, g);

  let gg = g.get();
  g.image(gg, v * g.width, 0);
  g.image(gg, -g.width + v * g.width, 0);

  lights();
  ambientLight(255);
  directionalLight(color(255), 0, 0, 1);
  orbitControl();

  push();
  // scale(20);
  rotateX(PI / 2);
  rotateY(0 + (PI / 2) * v + (vn * PI) / 2);
  texture(g);
  noStroke();
  cylinder(2500 / 2, 5000, 3 + 1, 1, false, false);
  pop();

  push();
  translate(0, 0, -2500);
  rotateZ(TWO_PI / 3 + (TWO_PI / 3) * v + (vn * TWO_PI) / 3);
  fill(0, 255);
  texture(g);
  rectMode(CENTER);
  square(0, 0, (2500 / sqrt(2)) * sqrt(3));
  pop();
  push();
  translate(0, 0, 2500);
  rotateZ(TWO_PI / 3 + (TWO_PI / 3) * v + (vn * TWO_PI) / 3);
  fill(0, 255);
  texture(g);
  rectMode(CENTER);
  square(0, 0, (2500 / sqrt(2)) * sqrt(3));
  pop();
}

function separateGrid(x, y, d, min_d, t, target) {
  let sepNum = int(random(1, 5));
  let w = d / sepNum;

  for (let i = x; i < x + d - 1; i += (Math.max(0.001, Math.abs(w)) || 1)) {
    for (let j = y; j < y + d - 1; j += (Math.max(0.001, Math.abs(w)) || 1)) {
      if (random(100) < 95 && w > min_d) {
        separateGrid(i, j, w, min_d, t, target);
      } else {
        let v =
          (i + w / 2 + (j + w / 2) * target.width) /
          (target.width * target.height);
        v += t * 2;
        v %= 1;
        v = easeInOutCirc(sq(v));
        target.push();
        target.fill(255, 0);
        target.translate(i + w / 2, j + w / 2);
        target.rotate((int(random(4)) * PI) / 2);
        target.translate(-w / 2, -w / 2);
        target.stroke(random(palette));
        target.strokeCap(PROJECT);
        target.strokeJoin(BEVEL);
        let n = int(noise(i + w / 2, j + w / 2, frameCount / 200) * 8);
        let colors = shuffle(palette.concat());
        target.drawingContext.setLineDash([constrain(w * (1 - t), 1, w)]);
        target.drawingContext.lineDashOffset = w * t;
        if (v > 0.01) {
          switch (n) {
            case 0:
              target.rectMode(CENTER);
              target.rect(w / 2, w / 2, w * v, w * v);
              break;
            case 1:
              target.circle(w / 2, w / 2, w * v);
              break;
            case 2:
              target.triangle(0, 0, w * v, 0, 0, w * v);
              break;
            case 3:
              target.arc(0, 0, w * 2, w * 2, 0, (PI / 2) * v, PIE);
              break;
            case 4:
              target.rectMode(CORNER);
              target.rect(0, 0, w * v, w * v);
              break;
            case 5:
              let w2 = (v * w) / 2;
              target.beginShape();
              target.vertex(w / 2 - w2, w / 2 - w2);
              target.vertex(w / 2 - w2, w / 2 + w2);
              target.vertex(w / 2 + w2, w / 2 - w2);
              target.vertex(w / 2 + w2, w / 2 + w2);
              target.endShape();
              break;
            case 6:
              let t1 = radians(45) - v * radians(45);
              let t2 = radians(45) + v * radians(45);
              let r = map(v, 0, 1, sqrt(2) * w, w);
              target.triangle(
                0,
                0,
                cos(t1) * r,
                sin(t1) * r,
                cos(t2) * r,
                sin(t2) * r
              );
              break;
            case 7:
              target.arc(0, 0, w * 2 * v, w * 2 * v, 0, PI / 2, PIE);
              break;
          }
          target.drawingContext.clip();
        }
        // target.drawingContext.globalAlpha=1/2;
        drawHatchFillSquare(w / 2, w / 2, w, (v + t) % 1, target, colors);
        // target.drawingContext.globalAlpha=1;
        target.pop();
      }
    }
  }
}

function drawHatchFillSquare(cx, cy, d, t, target, colors) {
  target.push();
  target.translate(cx, cy);
  // target.scale(0.8);
  target.rotate((int(random(4)) * TWO_PI) / 4);
  for (let j = 0; j < 2; j++) {
    let a = (random() + t + j / 2) % 1;
    let count = map(a, 0, 1, 1, d / 4);
    target.push();
    target.rotate(j * PI);
    target.translate(-d / 2, -d / 2);
    target.noFill();
    target.strokeWeight(Math.max(0.1, Math.abs((j % 2 == 0 ? t : 1 - t))) * 5);
    target.stroke(colors[j]);
    // target.strokeCap(ROUND);
    // target.strokeJoin(ROUND);
    if (j % 2 == 0) {
      target.beginShape();
      target.vertex(0, 0);
      for (let i = 0; i < count; i++) {
        let v = (i / count) * d;
        if (i % 2 == 0) {
          target.vertex(v, 0);
          target.vertex(v, d);
        } else {
          target.vertex(v, d);
          target.vertex(v, 0);
        }
      }
      target.vertex(d, d);
      target.vertex(d, 0);
      target.endShape();
    } else {
      target.beginShape();
      target.vertex(0, 0);
      for (let i = 0; i < count; i++) {
        let vStep = (1 / count) * d;
        let v = (i / count) * d;
        let v2 = d - v;
        if (i % 2 == 0) {
          target.vertex(0, v2);
          target.vertex(d, v2);
        } else {
          target.vertex(d, v2);
          target.vertex(0, v2);
        }
      }
      // target.vertex(d,d);
      // target.vertex(d,0);
      target.endShape();
    }
    target.pop();
  }
  target.pop();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
